    ('evil-hunter-1.411.hunter-info-v1', 'class_change:118', 'h3', 'Summon Phoenix', NULL, NULL, 'confirmed', 'resolved', 'class_change', 118, 'Summons the Phoenix to participate in the battle.', 'When attacking, there is a <color=#46CCFF>35%</color> chance of attacking the enemy by dealing as much damage as <color=#46CCFF>keepValue%</color> of DPS, and all damage taken by the enemy increases by <color=#46CCFF>secondValue%</color> for <color=#46CCFF>valueTime secs</color> (cannot be activated for <color=#46CCFF>keepTime secs</color> after attacking.)', 30, 3, 0, 0, '{"index":118,"job":2,"subJob":3,"thirdJob":0,"fourthJob":0,"maxLevel":30,"coolTime":0,"upCoolTime":0,"keepTime":2,"upKeepTime":0,"keepValue":210,"upKeepValue":10,"secondValue":3.4000000953674316,"upSecondValue":0.4000000059604645,"valueTime":3,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":100000,"addStudySoul":220}'::jsonb),
    ('evil-hunter-1.411.hunter-info-v1', 'class_change:119', 'h4', 'Meteor', NULL, NULL, 'confirmed', 'resolved', 'class_change', 119, 'Summons a massive meteor from the sky to attack.', 'Wide area attack by dealing as much damage as <color=#46CCFF>keepValue%</color> of DPS.', 30, 3, 0, 0, '{"index":119,"job":3,"subJob":3,"thirdJob":0,"fourthJob":0,"maxLevel":30,"coolTime":20,"upCoolTime":0,"keepTime":0,"upKeepTime":0,"keepValue":1017,"upKeepValue":27,"secondValue":0,"upSecondValue":0,"valueTime":0,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":100000,"addStudySoul":220}'::jsonb),
    ('evil-hunter-1.411.hunter-info-v1', 'class_change:120', 'h1', 'Cyclone', NULL, NULL, 'confirmed', 'resolved', 'class_change', 120, 'Rotates at high speed to attack nearby enemies while holding a weapon.', 'For <color=#46CCFF>keepTime secs</color>, deals as much damage as <color=#46CCFF>keepValue%</color> of own DPS, ignoring the enemy''s DEF and attacks every <color=#46CCFF>valueTime secs</color>. Reduces damage taken while casting by <color=#46CCFF>secondValue%</color>.', 30, 3, 3, 0, '{"index":120,"job":0,"subJob":3,"thirdJob":3,"fourthJob":0,"maxLevel":30,"coolTime":20,"upCoolTime":0,"keepTime":3,"upKeepTime":0,"keepValue":134,"upKeepValue":4,"secondValue":40,"upSecondValue":0,"valueTime":0.25,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":5,"addStudySoul":120}'::jsonb),
    ('evil-hunter-1.411.hunter-info-v1', 'class_change:121', 'h2', 'Execution', NULL, NULL, 'confirmed', 'resolved', 'class_change', 121, 'Unleashes the power of Darkness to strengthen oneself.', 'For <color=#46CCFF>keepTime secs</color>, the damage taken is reduced by <color=#46CCFF>25%</color> and ATK is amplified by <color=#46CCFF>keepValue%</color>. When attacking, there is a <color=#46CCFF>secondValue%</color> chance to ignore the enemy''s DEF and Evasion, and attack with as much damage as <color=#46CCFF>400%</color> of DPS.', 30, 3, 3, 0, '{"index":121,"job":1,"subJob":3,"thirdJob":3,"fourthJob":0,"maxLevel":30,"coolTime":30,"upCoolTime":0,"keepTime":10,"upKeepTime":0,"keepValue":42,"upKeepValue":2,"secondValue":20.5,"upSecondValue":0.5,"valueTime":0,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":5,"addStudySoul":120}'::jsonb),
    ('evil-hunter-1.411.hunter-info-v1', 'class_change:122', 'h3', 'Mystic Arrow', NULL, NULL, 'confirmed', 'resolved', 'class_change', 122, 'Uses arrows with mysterious power to enhance attacks.', 'Amplify own ATK by <color=#46CCFF>keepValue%</color>, ignores enemy''s Evasion and DEF with a chance of <color=#46CCFF>secondValue%</color> (applies to basic attacks, multi-shot only).', 30, 3, 3, 0, '{"index":122,"job":2,"subJob":3,"thirdJob":3,"fourthJob":0,"maxLevel":30,"coolTime":0,"upCoolTime":0,"keepTime":0,"upKeepTime":0,"keepValue":15.199999809265137,"upKeepValue":1.2000000476837158,"secondValue":15.199999809265137,"upSecondValue":1.2000000476837158,"valueTime":0,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":5,"addStudySoul":120}'::jsonb),
