    ('evil-hunter-1.411.hunter-info-v1', 'class_change:126', 'h2', 'Token of Punishment', NULL, NULL, 'confirmed', 'resolved', 'class_change', 126, 'Creates the Token of Punishment to enhance the caster during normal attacks.', 'During normal attacks, there is a <color=#46CCFF>secondValue%</color> chance to obtain a Token of Punishment. The token lasts for <color=#46CCFF>keepTime sec</color> and each token amplifies the caster''s ATK by <color=#46CCFF>keepValue%</color>. Up to 5 Tokens of Punishment can be held.', 10, 0, 0, 1, '{"index":126,"job":1,"subJob":0,"thirdJob":0,"fourthJob":1,"maxLevel":10,"coolTime":30,"upCoolTime":0,"keepTime":30,"upKeepTime":0,"keepValue":2,"upKeepValue":0,"secondValue":16,"upSecondValue":1,"valueTime":0,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":500,"addStudySoul":10}'::jsonb),
