    ('evil-hunter-1.411.hunter-info-v1', 'class_change:132', 'h5', 'Equitation', NULL, NULL, 'confirmed', 'resolved', 'class_change', 132, 'Reaches the pinnacle of horsemanship, unleashing great power while mounted.', 'The damage taken is reduced by <color=#46CCFF>keepValue%</color>, and using Round Slash casts two attacks (additional attack deals <color=#46CCFF>secondValue%</color> damage). Equitation is only applied while mounted, and the dragon of the Dragon Knight also counts as a mount.', 30, 1, 0, 0, '{"index":132,"job":4,"subJob":1,"thirdJob":0,"fourthJob":0,"maxLevel":30,"coolTime":0,"upCoolTime":0,"keepTime":0,"upKeepTime":0,"keepValue":8.399999618530273,"upKeepValue":0.4000000059604645,"secondValue":25.200000762939453,"upSecondValue":1.2000000476837158,"valueTime":0,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":100000,"addStudySoul":220}'::jsonb),
    ('evil-hunter-1.411.hunter-info-v1', 'class_change:133', 'h5', 'Shadow Strike', NULL, NULL, 'confirmed', 'resolved', 'class_change', 133, 'Imbues the spear with the power of shadows, driving it into the enemy''s body.', 'Ignore the enemy''s evasion and attack them with damage equal to <color=#46CCFF>keepValue%</color> of the hunter''s DPS and stun them for <color=#46CCFF>valueTime sec</color>. At the start of a PvP match, the Shadow Lancer will not be selected for the first targeting for <color=#46CCFF>keepTime sec</color>, and will teleport to the furthest enemy.', 30, 2, 0, 0, '{"index":133,"job":4,"subJob":2,"thirdJob":0,"fourthJob":0,"maxLevel":30,"coolTime":15,"upCoolTime":0,"keepTime":1.5,"upKeepTime":0,"keepValue":1050,"upKeepValue":50,"secondValue":0,"upSecondValue":0,"valueTime":2.5,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":100000,"addStudySoul":220}'::jsonb),
