    ('evil-hunter-1.411.hunter-info-v1', 'class_change:136', 'h5', 'Shade Javelin', NULL, NULL, 'confirmed', 'resolved', 'class_change', 136, 'Throws a spear imbued with the power of wraiths, instilling terror in the enemy.', 'Attacks the enemy with damage equal to <color=#46CCFF>keepValue%</color> of the hunter''s DPS. The attack ignores the enemy''s evasion and makes them panic for <color=#46CCFF>valueTime sec</color>.', 30, 2, 2, 0, '{"index":136,"job":4,"subJob":2,"thirdJob":2,"fourthJob":0,"maxLevel":30,"coolTime":15,"upCoolTime":0,"keepTime":0,"upKeepTime":0,"keepValue":970,"upKeepValue":70,"secondValue":0,"upSecondValue":0,"valueTime":1.100000023841858,"upValueTime":0.10000000149011612,"valueCount":0,"upValueCount":0,"firstStudySoul":5,"addStudySoul":120}'::jsonb),
    ('evil-hunter-1.411.hunter-info-v1', 'class_change:137', 'h5', 'Dragon Breath', NULL, NULL, 'confirmed', 'resolved', 'class_change', 137, 'Unleashes a fiery breath from the mounted dragon''s mouth to burn enemies.', 'For <color=#46CCFF>keepTime sec</color>, deal AoE attacks with damage equal to <color=#46CCFF>keepValue%</color> of the hunter''s DPS every <color=#46CCFF>valueTime sec</color>. When casting Dragon Breath, become immune to status effects that limit actions.', 30, 3, 3, 0, '{"index":137,"job":4,"subJob":3,"thirdJob":3,"fourthJob":0,"maxLevel":30,"coolTime":20,"upCoolTime":0,"keepTime":2,"upKeepTime":0,"keepValue":207,"upKeepValue":17,"secondValue":0,"upSecondValue":0,"valueTime":0.4000000059604645,"upValueTime":0,"valueCount":0,"upValueCount":0,"firstStudySoul":5,"addStudySoul":120}'::jsonb),
